select entity_key, event_date, metric_value, lagInFrame(metric_value, 1, 0) over w as previous_value, leadInFrame(metric_value) over w as next_value, nth_value(metric_value, 2) over w as second_value, first_value(metric_value) over w as first_seen_value, last_value(metric_value) over w as last_seen_value from anon.metrics_store window w as (partition by entity_key order by event_date rows between unbounded preceding and unbounded following)